    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        float distance = 12f; //todo: scale with power
        Vec3 forward = entity.getForward();
        Vec3 end = Utils.raycastForBlock(level, entity.getEyePosition(), entity.getEyePosition().add(forward.scale(distance)), ClipContext.Fluid.NONE).getLocation();
        AABB hitbox = entity.getHitbox().expandTowards(end.subtract(entity.getEyePosition())).inflate(2);
        var targetableEntities = level.getEntities(entity, hitbox, e ->
                !e.isSpectator() &&
                        (e instanceof LivingEntity || e instanceof Projectile) &&
                        e.getBoundingBox().getCenter().subtract(entity.getBoundingBox().getCenter()).normalize().dot(entity.getForward()) >= .85);
        targetableEntities.sort(Comparator.comparingDouble(e -> e.distanceToSqr(entity)));
        if (!targetableEntities.isEmpty() && targetableEntities.get(0).distanceToSqr(entity) < distance * distance) {
            var closestEntity = targetableEntities.get(0);

            float radius = 2.5f;
            AABB damageBox = AABB.ofSize(closestEntity.getBoundingBox().getCenter(), radius, radius + 1, radius).move(forward.scale(radius / 2));
            // dampen end position by taking average of it and the impact location
            end = damageBox.getCenter().add(end).scale(0.5);
            var damageEntities = level.getEntities(entity, damageBox);
            var damageSource = this.getDamageSource(entity);
            boolean projectileEffects = false;
            for (Entity targetEntity : damageEntities) {
                if (targetEntity instanceof Projectile projectile &&
                        !projectile.noPhysics &&
                        !(projectile instanceof AbstractArrow arrow && ((AbstractArrowAccessor) arrow).isInGround()) &&
                        !projectile.getType().is(ModTags.CANT_PARRY)) {
                    projectileEffects = true;
                    projectile.setOwner(entity);
                    projectile.shoot(forward.x, forward.y, forward.z, (float) projectile.getDeltaMovement().length(), 0f);
                } else if (targetEntity.isAlive() &&
                        entity.isPickable() &&
                        Utils.hasLineOfSight(level, entity.getEyePosition(), targetEntity.getBoundingBox().getCenter(), true)) {
                    if (DamageSources.applyDamage(targetEntity, getDamage(spellLevel, entity), damageSource)) {
                        MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, targetEntity.getX(), targetEntity.getY() + targetEntity.getBbHeight() * .5f, targetEntity.getZ(), 15, targetEntity.getBbWidth() * .5f, targetEntity.getBbHeight() * .5f, targetEntity.getBbWidth() * .5f, .25, false);
                        EnchantmentHelper.doPostAttackEffects((ServerLevel) level, targetEntity, damageSource);
//                        targetEntity.setDeltaMovement(targetEntity.getDeltaMovement().add(end.subtract(targetEntity.position()).scale(1 / 6f)));
                        Vec3 knockback = targetEntity.position().subtract(entity.position()).normalize().add(0, 0.5, 0).normalize();
                        knockback.scale(Utils.random.nextIntBetweenInclusive(70, 100) / 100f *
                                Utils.clampedKnockbackResistanceFactor(targetEntity, .2f, 1f) * .1f);
                        targetEntity.setDeltaMovement(targetEntity.getDeltaMovement().add(knockback));

                        targetEntity.hurtMarked = true;
                    }
                }
            }
            if (projectileEffects) {
                level.playSound(null, closestEntity.getX(), closestEntity.getY(), closestEntity.getZ(), SoundRegistry.FIRE_DAGGER_PARRY.get(), entity.getSoundSource());
                MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, closestEntity.getX(), closestEntity.getY() + closestEntity.getBbHeight() * .5f, closestEntity.getZ(), 25, 0, 0, 0, .4, false);
            }
        }
        Vec3 rayVector = end.subtract(entity.getEyePosition());
        Vec3 impulse = rayVector.scale(1 / 6f).add(0, 0.1, 0);
        entity.setDeltaMovement(entity.getDeltaMovement().scale(0.2).add(impulse));
        entity.hurtMarked = true;
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.FALL_DAMAGE_IMMUNITY, 20, 0, false, false, true));

        forward = impulse.normalize(); // recalculate forward as the direction we are actually moving
        Vec3 up = new Vec3(0, 1, 0);
        if (forward.dot(up) > .999) {
            up = new Vec3(1, 0, 0);
        }
        Vec3 right = up.cross(forward);
        Vec3 particlePos = end.subtract(forward.scale(3)).add(right.scale(-0.3));
        MagicManager.spawnParticles(level,
                new EnderSlashParticleOptions(
                        (float) forward.x,
                        (float) forward.y,
                        (float) forward.z,
                        (float) right.x,
                        (float) right.y,
                        (float) right.z,
                        1f),
                particlePos.x, particlePos.y + .3, particlePos.z, 1, 0, 0, 0, 0, true);
        int trailParticles = 15;
        double speed = rayVector.length() / 12.0 * .75;
        for (int i = 0; i < trailParticles; i++) {
            Vec3 particleStart = entity.getBoundingBox().getCenter().add(Utils.getRandomVec3(1 + entity.getBbWidth()));
            Vec3 particleEnd = particleStart.add(rayVector);
            MagicManager.spawnParticles(level, new TraceParticleOptions(Utils.v3f(particleEnd), new Vector3f(1f, .333f, 1f)), particleStart.x, particleStart.y, particleStart.z, 1, 0, 0, 0, speed, false);
        }

        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

public static boolean applyDamage(Entity target, float baseAmount, DamageSource damageSource) {
    if (target instanceof LivingEntity livingTarget && damageSource instanceof SpellDamageSource spellDamageSource) {
        var e = new SpellDamageEvent(livingTarget, baseAmount, spellDamageSource);
        if (NeoForge.EVENT_BUS.post(e).isCanceled()) {
            return false;
        }
        baseAmount = e.getAmount();
        float adjustedDamage = baseAmount * getResist(livingTarget, spellDamageSource.spell.getSchoolType());
        if (damageSource.getDirectEntity() instanceof NoKnockbackProjectile) {
            ignoreNextKnockback(livingTarget);
        }
        if (damageSource.getEntity() instanceof LivingEntity livingAttacker) {
            if (isFriendlyFireBetween(livingAttacker, livingTarget)) {
                return false;
            }
            livingAttacker.setLastHurtMob(target);
        }
        return livingTarget.hurt(damageSource, adjustedDamage);
    } else {
        return target.hurt(damageSource, baseAmount);
    }
}

private static Supplier<AbstractSpell> registerSpell(AbstractSpell spell) {
    return SPELLS.register(spell.getSpellName(), () -> spell);
}

public static void onLivingChangeTarget(LivingChangeTargetEvent event) {
    var newTarget = event.getNewAboutToBeSetTarget();
    var entity = event.getEntity();
    if (newTarget != null) {
        //Prevent Village allies (ie preists/iron golems) from aggroing eachother
        if (newTarget.getType().is(ModTags.VILLAGE_ALLIES) && entity.getType().is(ModTags.VILLAGE_ALLIES)) {
            event.setCanceled(true);
            return;
        }
        //Prevent mobs who auto-target hostile mobs from targeting "enemy" summons, unless they are actually fighting
        if (newTarget instanceof IMagicSummon summon && summon instanceof Enemy && !(entity.equals(((Mob) newTarget).getTarget()))) {
            event.setCanceled(true);
            return;
        }
        if (newTarget.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY)) {
            event.setCanceled(true);
            return;
        }
    }
}

public void onCast(Level world, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    entity.addEffect(new MobEffectInstance(MobEffectRegistry.TRUE_INVISIBILITY, getDuration(spellLevel, entity), 0, false, false, true));
    int i = 0;
    for (var armor : entity.getArmorSlots()) {
        i++;
        var particle = armor.isEmpty() ? new SparkParticleOptions(0.5f, 0.5f, 0.5f) : new ItemParticleOption(ParticleTypes.ITEM, armor);
        MagicManager.spawnParticles(world, particle, entity.getX(), entity.getY(i / 4f), entity.getZ(), 10, .1, 0, .1, 0.1, false);
    }
    super.onCast(world, spellLevel, entity, castSource, playerMagicData);
}

public void onEffectAdded(LivingEntity livingEntity, int pAmplifier) {
    super.onEffectAdded(livingEntity, pAmplifier);

    var targetingCondition = TargetingConditions.forCombat().ignoreLineOfSight().selector(e -> {
        //IronsSpellbooks.LOGGER.debug("InvisibilitySpell TargetingConditions:{}", e);
        return (((Mob) e).getTarget() == livingEntity);
    });

    //remove aggro from anything targeting us
    livingEntity.level.getNearbyEntities(Mob.class, targetingCondition, livingEntity, livingEntity.getBoundingBox().inflate(40D))
            .forEach(entityTargetingCaster -> {
                //IronsSpellbooks.LOGGER.debug("InvisibilitySpell Clear Target From:{}", entityTargetingCaster);
                entityTargetingCaster.setTarget(null);
                entityTargetingCaster.targetSelector.getAvailableGoals().forEach(WrappedGoal::stop);
                entityTargetingCaster.getBrain().eraseMemory(MemoryModuleType.ATTACK_TARGET);
            });
}

public static void onDealDamage(LivingIncomingDamageEvent event) {
    if (event.getSource().getEntity() instanceof LivingEntity livingAttacker && livingAttacker.hasEffect(MobEffectRegistry.TRUE_INVISIBILITY)) {
        livingAttacker.removeEffect(MobEffectRegistry.TRUE_INVISIBILITY);
    }
}

public void entityInside(@NotNull BlockState state, @NotNull Level worldIn, @NotNull BlockPos pos, @NotNull Entity entityIn) {
    super.entityInside(state, worldIn, pos, entityIn);
    List<Entity> entities = worldIn.getEntitiesOfClass(Entity.class, getShape(state, worldIn, pos, CollisionContext.empty()).bounds().move(pos), EntitySelector.NO_SPECTATORS.and((p_289691_) -> {
        return !p_289691_.isIgnoringBlockTriggers();
    }));
    if (!entities.isEmpty() && worldIn.getBlockEntity(pos) instanceof RuneTile rune) {
        if (rune.spell != null) {
            // Ignore form and its augment, only check effects
            for (AbstractSpellPart part : rune.spell.recipe()) {
                if (part instanceof AbstractEffect) {
                    // If the effect is not a filter, proceed with rune activation
                    if (part instanceof IFilter filter) {
                        // If one or more filters are detected, all must match to let the rune activate
                        if (!filter.shouldResolveOnEntity(new EntityHitResult(entityIn), worldIn)) {
                            return;
                        }
                    } else break;
                }
            }
        }
        rune.touchedEntity = entities.getFirst();
        worldIn.scheduleTick(pos, this, 1);
    }
}

public void onResolve(HitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    BlockPos pos = BlockPos.containing(rayTraceResult.getLocation());
    if (rayTraceResult instanceof BlockHitResult blockHit && blockHit.isInside()) {
        pos = pos.relative(blockHit.getDirection());
    }
    SpellContext newContext = spellContext.makeChildContext();
    spellContext.setCanceled(true);
    if (world.getBlockState(pos).canBeReplaced()) {
        if (!world.isInWorldBounds(pos))
            return;
        if (!BlockUtil.destroyRespectsClaim(getPlayer(shooter, (ServerLevel) world), world, pos))
            return;
        BlockState placementState = BlockRegistry.RUNE_BLOCK.get().getStateForPlacement(new BlockPlaceContext(getPlayer(shooter, (ServerLevel) world), InteractionHand.MAIN_HAND, ItemStack.EMPTY, rayTraceResult instanceof BlockHitResult blockHit ? blockHit : new BlockHitResult(rayTraceResult.getLocation(), Direction.UP, pos, false)));
        if (placementState == null) return;
        world.setBlockAndUpdate(pos, placementState);
        if (world.getBlockEntity(pos) instanceof RuneTile runeTile) {
            if (shooter instanceof Player) {
                runeTile.uuid = shooter.getUUID();
            }
            runeTile.isTemporary = true;
            Spell newSpell = newContext.getSpell();
            var mutable = newSpell.mutable();
            mutable.recipe.addFirst(MethodTouch.INSTANCE);
            runeTile.isSensitive = spellStats.isSensitive();
            runeTile.setSpell(mutable.immutable());
        }
    }
}

public void tick(@NotNull BlockState state, @NotNull ServerLevel worldIn, @NotNull BlockPos pos, @NotNull RandomSource rand) {
    super.tick(state, worldIn, pos, rand);

    if (worldIn.getBlockEntity(pos) instanceof RuneTile rune && rune.touchedEntity != null) {
        rune.castSpell(rune.touchedEntity);
        rune.touchedEntity = null;
    }
}

public void castSpell(Entity entity) {
    if (entity == null)
        return;
    if (!this.isCharged || spell.isEmpty() || !(level instanceof ServerLevel serverLevel) || !(spell.get(0) instanceof MethodTouch))
        return;
    if (!this.isTemporary && this.disabled) return;
    try {
        Player playerEntity = uuid != null ? FakePlayerFactory.get(serverLevel, new GameProfile(uuid, "")) : ANFakePlayer.getPlayer(serverLevel);
        if (this.isSensitive) {
            Player onlinePlayer = serverLevel.getServer().getPlayerList().getPlayer(uuid);
            if (onlinePlayer != null) {
                playerEntity = onlinePlayer;
            }
        }
        EntitySpellResolver resolver = new EntitySpellResolver(new SpellContext(entity.level, spell, playerEntity, new RuneCaster(this, SpellContext.CasterType.RUNE)));
        resolver.onCastOnEntity(ItemStack.EMPTY, entity, InteractionHand.MAIN_HAND);

        if (this.isTemporary) {
            level.destroyBlock(worldPosition, false);
            return;
        }
        this.isCharged = false;

        level.setBlockAndUpdate(worldPosition, level.getBlockState(worldPosition).cycle(RuneBlock.POWERED));
        ticksUntilCharge = 20 * 2;
        updateBlock();
    } catch (Exception e) {
        PortUtil.sendMessage(entity, Component.translatable("ars_nouveau.rune.error"));
        e.printStackTrace();
        level.destroyBlock(worldPosition, false);
    }
}

public void tick() {

    if (level == null)
        return;
    if (!level.isClientSide) {
        if (--ticksUntilCharge > 0) {
            return;
        }
    }
    if (this.isCharged)
        return;
    if (!level.isClientSide && this.isTemporary) {
        level.destroyBlock(this.worldPosition, false);
    }
    if (!level.isClientSide) {
        List<ISpecialSourceProvider> provider = SourceUtil.takeSourceMultipleWithParticles(worldPosition, level, 10, spell.getCost());
        if (provider != null) {
            this.isCharged = true;
            level.setBlockAndUpdate(worldPosition, level.getBlockState(worldPosition).cycle(RuneBlock.POWERED));
            updateBlock();
        } else {
            ticksUntilCharge = 20 * 3;
            updateBlock();
        }
    }
}

public void saveAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
    super.saveAdditional(tag, pRegistries);
    tag.put("spell", ANCodecs.encode(Spell.CODEC.codec(), spell));
    tag.putBoolean("charged", isCharged);
    tag.putBoolean("redstone", disabled);
    tag.putBoolean("temp", isTemporary);
    tag.putInt("cooldown", ticksUntilCharge);
    if (uuid != null)
        tag.putUUID("uuid", uuid);
    tag.putBoolean("sensitive", isSensitive);
    tag.putString("pattern", pattern);
}

protected void loadAdditional(@NotNull CompoundTag tag, HolderLookup.@NotNull Provider pRegistries) {
    super.loadAdditional(tag, pRegistries);
    this.spell = ANCodecs.decode(Spell.CODEC.codec(), tag.getCompound("spell"));
    this.isCharged = tag.getBoolean("charged");
    this.disabled = tag.getBoolean("redstone");
    this.isTemporary = tag.getBoolean("temp");
    this.ticksUntilCharge = tag.getInt("cooldown");
    if (tag.contains("uuid"))
        this.uuid = tag.getUUID("uuid");
    this.isSensitive = tag.getBoolean("sensitive");
    this.pattern = tag.getString("pattern");
}

package com.hollingsworth.arsnouveau.api.spell;

import net.minecraft.world.InteractionHand;
import net.minecraft.world.entity.LivingEntity;
import net.minecraft.world.item.ItemStack;

/**
 * A special Spell resolver that ignores player limits such as mana.
 */
public class EntitySpellResolver extends SpellResolver {

    public EntitySpellResolver(SpellContext context) {
        super(context);
    }

    public void onCastOnEntity(LivingEntity target) {
        super.onCastOnEntity(ItemStack.EMPTY, target, InteractionHand.MAIN_HAND);
    }

    @Override
    protected boolean enoughMana(LivingEntity entity) {
        return true;
    }
}

public boolean onCastOnEntity(ItemStack stack, Entity target, InteractionHand hand) {
    if (canCast(spellContext.getUnwrappedCaster()) && !postEvent().isCanceled()) {
        this.hitResult = new EntityHitResult(target);
        CastResolveType resolveType = castType.onCastOnEntity(stack, spellContext.getUnwrappedCaster(), target, hand, getCastStats(), spellContext, this);
        if (resolveType == CastResolveType.SUCCESS) {
            expendMana();
        }
        return resolveType.wasSuccess;
    }
    return false;
}

public void onResolveEffect(Level world, HitResult result) {
    if (world.isClientSide) {
        return;
    }
    this.hitResult = result;
    this.resolveAllEffects(world);
}

protected void resolveAllEffects(Level world) {
    if (world.isClientSide) {
        return;
    }
    spellContext.resetCastCounter();
    resume(world);
}

public void resume(Level world) {
    if (world.isClientSide) {
        return;
    }
    LivingEntity shooter = spellContext.getUnwrappedCaster();
    SpellResolveEvent.Pre spellResolveEvent = new SpellResolveEvent.Pre(world, shooter, this.hitResult, spell, spellContext, this);
    NeoForge.EVENT_BUS.post(spellResolveEvent);
    if (spellResolveEvent.isCanceled())
        return;
    BlockPos hitPos = this.hitResult instanceof BlockHitResult blockHitResult ? blockHitResult.getBlockPos() : null;
    Entity hitEntity = this.hitResult instanceof EntityHitResult entityHitResult ? entityHitResult.getEntity() : null;
    while (spellContext.hasNextPart()) {
        AbstractSpellPart part = spellContext.nextPart();
        if (part == null)
            break;
        if (part instanceof AbstractAugment || !part.isEnabled())
            continue;
        SpellStats.Builder builder = new SpellStats.Builder();
        List<AbstractAugment> augments = spell.getAugments(spellContext.getCurrentIndex() - 1, shooter);
        SpellStats stats = builder
                .setAugments(augments)
                .addItemsFromEntity(shooter)
                .build(part, this.hitResult, world, shooter, spellContext);
        if (!(part instanceof AbstractEffect effect))
            continue;

        EffectResolveEvent.Pre preEvent = new EffectResolveEvent.Pre(world, shooter, this.hitResult, spell, spellContext, effect, stats, this);
        NeoForge.EVENT_BUS.post(preEvent);
        if (preEvent.isCanceled())
            continue;

        IResolveListener.ResolveStatus resolveStatus = IResolveListener.ResolveStatus.CONTINUE;

        if (hitPos != null) {
            var resolveListener = world.getCapability(CapabilityRegistry.BLOCK_SPELL_RESOLVE_CAP, hitPos);
            if (resolveListener != null)
                resolveStatus = resolveListener.onPreResolve(world, shooter, this.hitResult, spell, spellContext, effect, stats, this);
        }

        if (hitEntity != null) {
            var resolveListener = hitEntity.getCapability(CapabilityRegistry.ENTITY_SPELL_RESOLVE_CAP);
            if (resolveListener != null)
                resolveStatus = resolveListener.onPreResolve(world, shooter, this.hitResult, spell, spellContext, effect, stats, this);
        }

        if (resolveStatus == IResolveListener.ResolveStatus.STOP_ALL) {
            NeoForge.EVENT_BUS.post(new EffectResolveEvent.Post(world, shooter, this.hitResult, spell, spellContext, effect, stats, this));
            break;
        } else if (resolveStatus == IResolveListener.ResolveStatus.CONTINUE) {
            effect.onResolve(this.hitResult, world, shooter, stats, spellContext, this);
        }

        if (hitPos != null) {
            var resolveListener = world.getCapability(CapabilityRegistry.BLOCK_SPELL_RESOLVE_CAP, hitPos);
            if (resolveListener != null)
                resolveListener.onPostResolve(world, shooter, this.hitResult, spell, spellContext, effect, stats, this);
        }

        if (hitEntity != null) {
            var resolveListener = hitEntity.getCapability(CapabilityRegistry.ENTITY_SPELL_RESOLVE_CAP);
            if (resolveListener != null)
                resolveListener.onPostResolve(world, shooter, this.hitResult, spell, spellContext, effect, stats, this);
        }

        NeoForge.EVENT_BUS.post(new EffectResolveEvent.Post(world, shooter, this.hitResult, spell, spellContext, effect, stats, this));
    }

    NeoForge.EVENT_BUS.post(new SpellResolveEvent.Post(world, shooter, this.hitResult, spell, spellContext, this));
}

public CastResolveType onCastOnEntity(ItemStack stack, LivingEntity caster, Entity target, InteractionHand hand, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    resolver.onResolveEffect(caster.getCommandSenderWorld(), new EntityHitResult(target));
    ParticleEmitter particleEmitter = resolveEmitter(spellContext, target.position);
    particleEmitter.tick(caster.level);
    playResolveSound(spellContext, caster.level(), target.position());
    addFadingLight(caster.level(), target.blockPosition().getX() + 0.5, target.blockPosition().getY() + 0.5, target.blockPosition().getZ() + 0.5);
    return spellContext.getCaster().getCasterType() != SpellContext.CasterType.RUNE ? CastResolveType.SUCCESS : CastResolveType.SUCCESS_NO_EXPEND;
}

