package com.hollingsworth.arsnouveau.common.block;

import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.EntityBlock;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.entity.BlockEntityTicker;
import net.minecraft.world.level.block.entity.BlockEntityType;
import net.minecraft.world.level.block.state.BlockState;

import javax.annotation.Nullable;

public interface ITickableBlock extends EntityBlock {
    @Nullable
    @Override
    default <T extends BlockEntity> BlockEntityTicker<T> getTicker(final Level level, final BlockState state, final BlockEntityType<T> type) {
        return createTickerHelper(type, type, (l, pos, s, te) -> ((ITickable) te).tick(l, s, pos));
    }

    @Nullable
    static <E extends BlockEntity, A extends BlockEntity> BlockEntityTicker<A> createTickerHelper(BlockEntityType<A> type1, BlockEntityType<E> type2, BlockEntityTicker<? super E> ticker) {
        return type2 == type1 ? (BlockEntityTicker<A>) ticker : null;
    }
}

public static void performAttackAgainstTargets(ServerPlayerEntity player, AttackContext context, int[] targetIds) {
    var world = player.getWorld();
    var focusMode = focusMode();
    var attributeInstance = player.getAttributes().getCustomInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE);
    EntityAttributeModifier appliedDamageModifier = null;
    EntityAttributeModifier appliedDualWieldModifier = null;
    EntityAttributeModifier appliedChargeModifier = null;
    // Arrived from the client, so it is never trusted as-is.
    var curvedRatio = MathHelper.clamp(context.charge(), 0F, 1F);
    try {
        var lastAttackTime = ((LivingEntityAccessor)player).spellEngine_getLastAttackedTicks();
        var targets = new ArrayList<Entity>();
        var resolvedContext = resolveAttackData(player, world, context.spellId, context.attackId);
        var spellEntry = resolvedContext.spell();
        ((SpellCaster.Player)player).setActiveMeleeSkill(spellEntry);
        var attack = resolvedContext.attack();
        Sound impactSound = null;
        int impactSoundLimit = 0;
        var resolvedCharge = resolveCharge(spellEntry, curvedRatio);
        var charge = resolvedCharge.outputMultiplier();
        var modifiers = SpellModifiers.of(player, spellEntry, resolvedCharge.modifier());
        var damageMultiplierBase = 0F;
        for (var modifier : modifiers) {
            damageMultiplierBase += modifier.melee_damage_multiplier;
        }
        // Read before any temporary modifier lands, so it cannot inflate its own ratio. Kept as a
        // separate modifier rather than summed into the one below: `ADD_MULTIPLIED_TOTAL`
        // modifiers compose multiplicatively, so this way percentage bonuses scale the dual
        // wielded swing instead of the main hand one.
        var dualWieldBonus = dualWieldDamageBonus(player, spellEntry != null ? spellEntry.value() : null);
        if (dualWieldBonus != 0 && attributeInstance != null) {
            appliedDualWieldModifier = new EntityAttributeModifier(DUAL_WIELD_MODIFIER_ID, dualWieldBonus, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
            attributeInstance.addTemporaryModifier(appliedDualWieldModifier);
        }
        // Melee skills land their damage through vanilla `player.attack(...)`, which the
        // `ImpactContext` never reaches, so a partial CHARGE release scales the swing here.
        // Kept separate for the same reason as the dual wield bonus: `ADD_MULTIPLIED_TOTAL`
        // modifiers compose multiplicatively, so the charge scales the whole swing rather
        // than being diluted by the flat bonuses below.
        if (charge != 1F && attributeInstance != null) {
            appliedChargeModifier = new EntityAttributeModifier(CHARGE_MODIFIER_ID, charge - 1F, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
            attributeInstance.addTemporaryModifier(appliedChargeModifier);
        }
        if (attack != null && attributeInstance != null) {
            var damageModifierAmount = attack.damage_bonus + damageMultiplierBase;
            if (damageModifierAmount != 0) {
                appliedDamageModifier = new EntityAttributeModifier(DAMAGE_MODIFIER_ID, damageModifierAmount, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedDamageModifier);
            }
            impactSound = attack.impact_sound;
            impactSoundLimit = attack.impact_sound_cap > 0 ? attack.impact_sound_cap : 999;
        }
        var attackRange = spellEntry != null ? SpellParameters.getRangeCurved(player, spellEntry, curvedRatio) : (float)player.getEntityInteractionRange();

        for (int targetId : targetIds) {
            var target = world.getEntityById(targetId);
            if (target != null && target.isAttackable()) {
                if (!EntityRelations.actionAllowed(
                        focusMode, SpellTarget.Intent.HARMFUL,
                        player, target)) {
                    continue;
                }

                var distanceGuard = (attackRange + largesSideLength(target.getBoundingBox())) * 1.2F; // Adding some tolerance
                if (player.squaredDistanceTo(target) > (distanceGuard * distanceGuard) ) {
                    continue;
                }

                var timeUntilRegen = target.timeUntilRegen;
                target.timeUntilRegen = 0;
                ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(100);
                player.attack(target);
                if (impactSound != null && impactSoundLimit > 0) {
                    SoundHelper.playSound(target.getWorld(), target, impactSound);
                    impactSoundLimit -= 1;
                }
                targets.add(target);
                target.timeUntilRegen = timeUntilRegen;
            }
        }

        if (!targets.isEmpty()) {
            var impactContext = new SpellExecution.ImpactContext()
                    .position(player.getPos())
                    .charge(curvedRatio)
                    .chargeModifier(resolvedCharge.modifier());
            SpellImpacts.meleeImpact(player, targets, spellEntry, impactContext);
        }
        ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(lastAttackTime);
    } catch (Exception e) {
        System.err.println("Failed to perform melee attack: " + e.getMessage());
    }
    if (appliedDamageModifier != null) {
        attributeInstance.removeModifier(appliedDamageModifier);
    }
    if (appliedDualWieldModifier != null) {
        attributeInstance.removeModifier(appliedDualWieldModifier);
    }
    if (appliedChargeModifier != null) {
        attributeInstance.removeModifier(appliedChargeModifier);
    }
    ((SpellCaster.Player)player).setActiveMeleeSkill(null);
}

public static void handleAttackPerform(Packets.AttackPerform packet, MinecraftServer server, ServerPlayerEntity player) {
    ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
            .orNull();
    if (world == null || world.isClient) {
        return;
    }

    world.getServer().executeSync(() -> {
        Melee.performAttackAgainstTargets(player, packet.attackContext(), packet.targetIds());
    });
}

@Nullable public static ResolutionResult resolveAttackData(PlayerEntity attacker, World world, Identifier spellId, String attackId) {
    var spellEntry = SpellRegistry.from(world).getEntry(spellId).orElse(null);
    if (spellEntry == null) {
        return null;
    }

    var spell = spellEntry.value();
    if (spell.deliver.type == Spell.Delivery.Type.MELEE && spell.deliver.melee != null) {
        var allAttacks = allAttacksOf(attacker, spell.deliver.melee.attacks, spellEntry);
        for (var attack : allAttacks.attacks()) {
            if (attack.id.equals(attackId)) {
                return new ResolutionResult(spellEntry, spell.deliver.melee, attack);
            }
        }
    }

    return null;
}

private static ResolvedCharge resolveCharge(@Nullable RegistryEntry<Spell> spellEntry, float curvedRatio) {
    var charge = SpellParameters.chargeConfigOf(spellEntry);
    if (charge == null) { return ResolvedCharge.NONE; }
    return new ResolvedCharge(
            SpellParameters.chargeOutputMultiplier(spellEntry, curvedRatio),
            SpellModifiers.scaledBy(charge.bonus, curvedRatio));
}

private static SpellTarget.FocusMode focusMode() {
    return SpellEngineMod.config.melee_skills_area_focus_mode ? SpellTarget.FocusMode.AREA : SpellTarget.FocusMode.DIRECT;
}

private static float largesSideLength(Box boundingBox) {
    double x = boundingBox.getLengthX();
    double y = boundingBox.getLengthY();
    double z = boundingBox.getLengthZ();
    return Math.max((float)x, Math.max((float)y, (float)z));
}

public static boolean meleeImpact(LivingEntity caster, List<Entity> targets, RegistryEntry<Spell> spellEntry, @Nullable ImpactContext context) {
    var spell = spellEntry.value();
    var anySuccess = false;
    if (spell.impacts != null) {
        if (context.power() == null) {
            context = context.power(SpellPower.getSpellPower(spell.school, caster));
        }

        var world = caster.getWorld();
        var casterPos = caster.getPos().add(0, caster.getHeight() / 2F, 0);

        for(var target: targets) {
            var position = target == caster
                    ? casterPos
                    : target.getPos().add(0, target.getHeight() / 2F, 0).lerp(casterPos, 0.01F);
            var targetSpecificContext = context.position(position);
            var result = performImpacts(world, caster, target, target, spellEntry, spell.impacts, targetSpecificContext);
            anySuccess = anySuccess || result;
        }
    }
    return anySuccess;
}

public static boolean deliver(World world, RegistryEntry<Spell> spellEntry, LivingEntity caster, List<DeliveryTarget> targets, ImpactContext context,
                              @Nullable Vec3d targetLocation, @Nullable Consumer<DeliveryCompletion> completion, boolean forceSuccess, boolean scheduled) {
    var spell = spellEntry.value();

    if (spell.deliver.delay > 0) {
        if (scheduled) {
            Predicate<Entity> validator = (entity) -> !(entity == null || entity.isRemoved());
            if (!validator.test(caster)) {
                return false;
            }
            targets = targets.stream().filter(target -> validator.test(target.entity())).toList();
        } else {
            List<DeliveryTarget> finalTargets = targets;
            ((WorldScheduler) world).schedule(spell.deliver.delay, () -> deliver(world, spellEntry, caster, finalTargets, context, targetLocation, completion, forceSuccess, true));
            return true;
        }
    }

    var delivered = false;
    switch (spell.deliver.type) {
        case DIRECT -> {
            var anySuccess = false;
            var casterPos = caster.getPos().add(0, caster.getHeight() / 2F, 0);
            if (targets.isEmpty() && targetLocation != null
                    && spell.area_impact != null) { // Special check to allow area impacts only, in the absence of targets
                var position = targetLocation.lerp(casterPos, 0.001F);
                var targetSpecificContext = context.position(position);
                SpellImpacts.performImpacts(world, caster, caster, null, spellEntry, spell.impacts, targetSpecificContext);
                anySuccess = true; // The area impact will be executed, hence always true
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var position = target == caster
                            ? casterPos
                            : target.getPos().add(0, target.getHeight() / 2F, 0).lerp(casterPos, 0.01F);
                    var targetSpecificContext = targeted.context().position(position);
                    var result = SpellImpacts.performImpacts(world, caster, target, target, spellEntry, spell.impacts, targetSpecificContext);
                    anySuccess = anySuccess || result;
                }
            }
            delivered = anySuccess;
        }
        case PROJECTILE -> {
            if (targets.isEmpty()) {
                ProjectileLauncher.shootProjectile(world, caster, null, spellEntry, context);
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    ProjectileLauncher.shootProjectile(world, caster, target, spellEntry, targetSpecificContext);
                }
            }
            delivered = true;
        }
        case METEOR -> {
            var anyLaunched = false;
            if (targets.isEmpty() && targetLocation != null) {
                ProjectileLauncher.fallProjectile(world, caster, null, targetLocation, spellEntry, context);
                anyLaunched = true;
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    ProjectileLauncher.fallProjectile(world, caster, target, null, spellEntry, targetSpecificContext);
                    anyLaunched = true;
                }
            }
            delivered = anyLaunched;
        }
        case CLOUD -> {
            var placedAny = false;
            if (targets.isEmpty() && targetLocation != null) {
                CloudPlacer.placeCloud(world, caster, null, targetLocation, spellEntry, context.position(targetLocation));
                placedAny = true;
            } else {
                for(var targeted: targets) {
                    var target = targeted.entity();
                    var targetSpecificContext = targeted.context();
                    CloudPlacer.placeCloud(world, caster, target, null, spellEntry, targetSpecificContext);
                    placedAny = true;
                }
            }
            delivered = placedAny;
        }
        case SHOOT_ARROW -> {
            ArrowHelper.shootArrow(world, caster, spellEntry, context);
            delivered = true;
        }
        case AFFECT_ARROW -> {
            if (caster instanceof SpellCaster.Player shooter) {
                var arrowContext = shooter.getArrowShootContext();
                arrowContext.activeSpells.add(spellEntry);
            }
            delivered = true;
        }
        case MELEE -> {
            if (spell.deliver.melee != null
                    && !spell.deliver.melee.attacks.isEmpty()) {
                var attackers = !targets.isEmpty()
                        ? targets.stream().map(e -> e.entity()).toList()
                        : List.of(caster);
                var meleeData = spell.deliver.melee;
                var spellId = spellEntry.getKey().get().getValue();
                var attacks = meleeData.attacks;
                if (context.isChanneled()) {
                    var index = context.channelTickIndex() % attacks.size();
                    attacks = List.of(attacks.get(index));
                }
                for (var attacker: attackers) {
                    if (!attacker.isOnGround() && !spell.deliver.melee.allow_airborne) {
                        break;
                    }
                    if (attacker instanceof ServerPlayerEntity serverPlayer) {
                        // Map to resolved MeleeAttack structures
                        var meleeAttacks = Melee.createMeleeAttacks(serverPlayer, attacks, spellEntry,
                                context.charge(), context.chargeModifier());
                        // Send AttackAvailable packet to client
                        var packet = new Packets.AttackAvailable(spellId, meleeAttacks);
                        Platform.util().networkS2C_Send(serverPlayer, packet);
                        delivered = true;
                    }
                }
            }
        }
        case STASH_EFFECT -> {
            var anyAdded = false;
            var stash = spell.deliver.stash_effect;
            var id = Identifier.of(stash.id);
            var effect = Registries.STATUS_EFFECT.getEntry(id).get();

            var amplifier = stash.amplifier;
            if (stash.amplifier_power_multiplier != 0) {
                var power = SpellPower.getSpellPower(spell.school, caster);
                amplifier += (int)(stash.amplifier_power_multiplier * power.nonCriticalValue());
            }
            for (var modifier: SpellModifiers.of(caster, spellEntry, context.chargeModifier())) {
                amplifier += modifier.stash_amplifier_add;
            }
            for (var targeted: targets) {
                if (targeted.entity() instanceof LivingEntity livingEntity) {
                    if (stash.stacking) {
                        var stack = -1;
                        var existingInstance = livingEntity.getStatusEffect(effect);
                        if (existingInstance != null) {
                            stack = existingInstance.getAmplifier();
                            livingEntity.removeStatusEffect(effect);
                        }
                        stack += 1;
                        var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), Math.min(stack, amplifier), false, stash.show_particles, true);
                        livingEntity.addStatusEffect(instance);
                    } else {
                        var instance = new StatusEffectInstance(effect, (int) (stash.duration * 20), amplifier, false, stash.show_particles, true);
                        livingEntity.addStatusEffect(instance);
                    }
                    anyAdded = true;
                }
            }
            delivered = anyAdded;
        }
        case CUSTOM -> {
            if (spell.deliver.custom != null) {
                var handler = SpellHandlers.customDelivery.get(spell.deliver.custom.handler);
                if (handler != null) {
                    delivered = handler.onSpellDelivery(world, spellEntry, caster, targets, context, targetLocation);
                }
            }
        }
    }

    if (completion != null) {
        completion.accept(new DeliveryCompletion(delivered || forceSuccess));
    }

    return delivered;
}

public static void init() {
    // Config stage
    PayloadTypeRegistry.configurationS2C().register(Packets.ConfigSync.PACKET_ID, Packets.ConfigSync.CODEC);
    PayloadTypeRegistry.configurationS2C().register(Packets.SpellRegistrySync.PACKET_ID, Packets.SpellRegistrySync.CODEC);
    PayloadTypeRegistry.configurationC2S().register(Packets.Ack.PACKET_ID, Packets.Ack.CODEC);

    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        // This if block is required! Otherwise the client gets stuck in connection screen
        // if the client cannot handle the packet.
        if (ServerConfigurationNetworking.canSend(handler, Packets.ConfigSync.ID)) {
            handler.addTask(new ConfigurationTask(SpellEngineMod.config));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.CONFIG_TASK_NAME));
        }
    });
    ServerConfigurationConnectionEvents.CONFIGURE.register((handler, server) -> {
        if (ServerConfigurationNetworking.canSend(handler, Packets.SpellRegistrySync.ID)) {
            if (SpellAssignments.encoded.isEmpty()) {
                throw new AssertionError("Spell registry is empty!");
            }
            handler.addTask(new SpellRegistrySyncTask(SpellAssignments.encoded));
        } else {
            handler.disconnect(Text.literal("Network configuration task not supported: " + ServerNetwork.SPELL_REGISTRY_TASK_NAME));
        }
    });
    ServerConfigurationNetworking.registerGlobalReceiver(Packets.Ack.PACKET_ID, (packet, context) -> {
        // Warning: if you do not call completeTask, the client gets stuck!
        if (packet.code().equals(ServerNetwork.CONFIG_TASK_NAME)) {
            context.networkHandler().completeTask(ConfigurationTask.KEY);
        }
        if (packet.code().equals(ServerNetwork.SPELL_REGISTRY_TASK_NAME)) {
            context.networkHandler().completeTask(SpellRegistrySyncTask.KEY);
        }
    });

    // Play stage
    PayloadTypeRegistry.playC2S().register(Packets.CastRequest.PACKET_ID, Packets.CastRequest.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.TargetStream.PACKET_ID, Packets.TargetStream.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.CastInput.PACKET_ID, Packets.CastInput.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackPerform.PACKET_ID, Packets.AttackPerform.CODEC);
    PayloadTypeRegistry.playC2S().register(Packets.AttackFxBroadcast.PACKET_ID, Packets.AttackFxBroadcast.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldown.PACKET_ID, Packets.SpellCooldown.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellCooldownSync.PACKET_ID, Packets.SpellCooldownSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellMessage.PACKET_ID, Packets.SpellMessage.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.ParticleEffects.PACKET_ID, Packets.ParticleEffects.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellAnimation.PACKET_ID, Packets.SpellAnimation.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.SpellContainerSync.PACKET_ID, Packets.SpellContainerSync.CODEC);
    PayloadTypeRegistry.playS2C().register(Packets.AttackAvailable.PACKET_ID, Packets.AttackAvailable.CODEC);

    ServerPlayNetworking.registerGlobalReceiver(Packets.CastRequest.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastRequest(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.TargetStream.PACKET_ID, (packet, context) ->
            ServerNetwork.handleTargetStream(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.CastInput.PACKET_ID, (packet, context) ->
            ServerNetwork.handleCastInput(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackFxBroadcast.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackFxBroadcast(packet, context.server(), context.player()));
    ServerPlayNetworking.registerGlobalReceiver(Packets.AttackPerform.PACKET_ID, (packet, context) ->
            ServerNetwork.handleAttackPerform(packet, context.server(), context.player()));
}

private void onTick_ScheduledAttacks(ClientPlayerEntity player) {
    var time = player.age;
    if (EntityActionsAllowed.isImpaired(player, EntityActionsAllowed.Player.ATTACK)) {
        currentAttack = null;
        return;
    }
    checkForNextAttack(player, time);
    if (currentAttack != null) {
        if (currentAttack.weapon != player.getMainHandStack().getItem()) {
            // Weapon changed, cancel attack
            currentAttack = null;
            return;
        }
        if (currentAttack.isDue(time)) {
            onAttackHit(currentAttack);
        }
        if (currentAttack.isFinished(time)) {
            currentAttack = null;
            checkForNextAttack(player, time);
        }
    }
}

public void onAttacksAvailable(List<Melee.Attack> attacks) {
    scheduledAttacks.addAll(attacks);
}

private void checkForNextAttack(ClientPlayerEntity player, int time) {
    if (currentAttack == null) {
        if (!scheduledAttacks.isEmpty()) {
            var attack = scheduledAttacks.remove(0);
            currentAttack = new Melee.ActiveAttack(attack, time, player.getMainHandStack().getItem());
            onAttackActivated(attack);
        }
    }
}

private void onAttackActivated(Melee.Attack attack) {
    // On attack started

    var player = player();
    var momentum = attack.forward_momentum();
    if (momentum > 0
            && (attack.allow_momentum_airborne() || player.isOnGround()) ) {
        var direction = new Vec3d(0, 0, 1)
                .rotateY((float) Math.toRadians((-1.0) * player.getYaw()))
                .multiply(attack.forward_momentum());
        player.addVelocity(direction.x, direction.y, direction.z);
    }

    if (attack.context() != null) {
        var animationSpeed = attack.speed() * attack.animation().speed;
        ((AnimatablePlayer)this).playSpellAnimation(SpellCast.Animation.RELEASE, attack.animation().id, animationSpeed);
        var packet = new Packets.AttackFxBroadcast(attack.context());
        Platform.util().networkC2S_Send(packet);
    }
}

private void onAttackHit(Melee.ActiveAttack activeAttack) {
    var player = player();
    var attack = activeAttack.attack;
    var targets = Melee.detectTargets(player, attack);
    if (!attack.additional_hits_on_same_target()) {
        targets = targets.stream().filter(id -> !activeAttack.hitEntityIds.contains(id)).toList();
    }
    activeAttack.hitEntityIds.addAll(targets);
    if (!targets.isEmpty()) {
        var targetIds = targets.stream().mapToInt(Integer::intValue).toArray();
        var context = attack.context() != null ? attack.context() : Melee.AttackContext.EMPTY;
        var packet = new Packets.AttackPerform(context, targetIds);
        Platform.util().networkC2S_Send(packet);
    }
}

private void tick_TAIL_SpellEngine(CallbackInfo ci) {
    var player = player();
    castController.tick();
    if (isBeaming()) {
        PlatformClient.util().sendVanillaPacket_C2S(player, new PlayerMoveC2SPacket.Full(
                player.getX(), player.getY(), player.getZ(),
                player.getYaw(), player.getPitch(),
                player.isOnGround())
        );
    }
    onTick_ScheduledAttacks(player);
}

public static void handleAttackAvailable(Packets.AttackAvailable packet) {
    var client = MinecraftClient.getInstance();
    client.execute(() -> {
        var player = client.player;
        if (player instanceof SpellCaster.Client caster) {
            caster.onAttacksAvailable(packet.attacks());
        }
    });
}

