public class Melee {

    public record Attack(
            int duration,
            int delay,
            int additional_strikes,
            int additional_strike_delay,
            boolean additional_hits_on_same_target,
            float speed,
            float forward_momentum,
            boolean allow_momentum_airborne,
            float movement_speed,
            float movement_slip,
            float range,
            Spell.Delivery.Melee.HitBox hitbox,
            PlayerAnimation animation,
            @Nullable AttackContext context
    ) {
    }
    /**
     * Context object that tracks the origin of a Melee.Attack
     * Allows mapping back from execution model to data model
     */
    public record AttackContext(
        Identifier spellId,
        String attackId,
        /// `curve(hold ratio)` of the CHARGE cast this attack was released from, in `0..1`;
        /// always `1` for every other cast type. Travels with the attack through the client round
        /// trip, so overlapping deliveries cannot mix up each other's charge.
        ///
        /// Same unweighted value `SpellExecution.ImpactContext` carries, under the same name — the
        /// output multiplier and the charge bonus are both rebuilt from it by `resolveCharge`.
        float charge
    ) {
        public static final AttackContext EMPTY = new AttackContext(Identifier.of("spell_engine", "empty"), "empty", 1F);
        /**
         * Create context for a specific attack
         */
        public static AttackContext of(Identifier spellId, String attackId, float charge) {
            return new AttackContext(spellId, attackId, charge);
        }
    }

    public static class ActiveAttack {
        public final Attack attack;
        public final int createdAt;
        public final Item weapon;
        public final Set<Integer> hitEntityIds = new HashSet<>();
        private final ArrayList<Integer> hitTicks;

        public ActiveAttack(Attack attack, int createdAt, Item weapon) {
            this.attack = attack;
            this.createdAt = createdAt;
            this.weapon = weapon;
            var ticks = new ArrayList<Integer>();
            var firstHit = createdAt + attack.delay;
            ticks.add(firstHit);
            for (int i = 1; i <= attack.additional_strikes; i++) {
                ticks.add(firstHit + (i * attack.additional_strike_delay));
            }
            this.hitTicks = ticks;
        }

        public boolean isFinished(int currentTick) {
            return currentTick >= (createdAt + attack.duration) && currentTick >= hitTicks.getLast();
        }

        public boolean isDue(int currentTick) {
            return hitTicks.contains(currentTick);
        }
    }


    public record CombinedAttacks(
            List<Spell.Delivery.Melee.Attack> attacks,
            List<Spell.Modifier> spellModifiers
    ) {}

    public static CombinedAttacks allAttacksOf(PlayerEntity caster, List<Spell.Delivery.Melee.Attack> meleeDataAttacks,
                                                                 RegistryEntry<Spell> spellEntry) {
        return allAttacksOf(caster, meleeDataAttacks, spellEntry, null);
    }

    /// `chargeModifier` is the charge bonus scaled by the curved ratio, or null outside CHARGE casts.
    /// It never contributes `melee_attacks` (stripped in `SpellModifiers.scaledBy`), so the returned
    /// attack list — and therefore every attack id — is identical with or without it. That is what
    /// lets `resolveAttackData` map an `AttackContext` back to its attack on the return leg.
    public static CombinedAttacks allAttacksOf(PlayerEntity caster, List<Spell.Delivery.Melee.Attack> meleeDataAttacks,
                                                                 RegistryEntry<Spell> spellEntry,
                                                                 @Nullable Spell.Modifier chargeModifier) {
        var attacks = new ArrayList<>(meleeDataAttacks);
        var modifiers = SpellModifiers.of(caster, spellEntry, chargeModifier);
        for (var modifier: modifiers) {
            if (modifier.melee_attacks != null) {
                for (var attack : modifier.melee_attacks) {
                    attacks.add(attack);
                }
            }
        }
        return new CombinedAttacks(attacks, modifiers);
    }

    /**
     * Server-side: Map spell melee configuration to resolved MeleeAttack list
     * This flattens and resolves all server-side calculations (haste, etc.)
     */
    public static List<Attack> createMeleeAttacks(ServerPlayerEntity caster, List<Spell.Delivery.Melee.Attack> meleeDataAttacks,
                                                  RegistryEntry<Spell> spellEntry, float curvedRatio,
                                                  @Nullable Spell.Modifier chargeModifier) {
        var attacks = new ArrayList<Attack>();
        var attackSpeedMultiplier = AttributeModifierUtil.multipliersOf(EntityAttributes.GENERIC_ATTACK_SPEED, caster);
        var spellId = spellEntry.getKey().get().getValue();
        var allAttacks = allAttacksOf(caster, meleeDataAttacks, spellEntry, chargeModifier);
        for (var attack : allAttacks.attacks()) {
            // Calculate haste-affected duration
            var meleeAttack = convert(caster, spellId, attack, attackSpeedMultiplier, allAttacks.spellModifiers(), curvedRatio);
            attacks.add(meleeAttack);
        }
        return attacks;
    }

    private static Attack convert(ServerPlayerEntity caster, Identifier spellId, Spell.Delivery.Melee.Attack attack, double attackSpeedMultiplier, List<Spell.Modifier> spellModifiers, float curvedRatio) {
        var speed = (float) (attack.attack_speed_multiplier * attackSpeedMultiplier);
        float duration = attack.duration > 0
                // `getAttackCooldownProgressPerTick` is poorly named, it actually returns the attack cooldown in ticks
                ? attack.duration
                : Math.max(caster.getAttackCooldownProgressPerTick() * (1F / speed), 1);
        float delay = duration * attack.delay;
        var spell = SpellRegistry.from(caster.getWorld()).getEntry(spellId);
        // Must stay in step with the server side distance guard in `performAttackAgainstTargets`,
        // which resolves the same range: a hitbox grown by `range_add` here but not there would
        // find targets the server then rejects.
        var range = spell.isPresent() ? SpellParameters.getRangeCurved(caster, spell.get(), curvedRatio) : (float)caster.getEntityInteractionRange();

        var momentumBonus = 0F;
        var slipBonus = 0F;
        for (var modifier : spellModifiers) {
            momentumBonus += modifier.melee_momentum_add;
            slipBonus += modifier.melee_slipperiness_add;
        }

        // Create resolved MeleeAttack with all calculations done
        return new Attack(
                Math.round(duration),
                Math.round(delay),
                attack.additional_strikes,
                Math.max(Math.round(duration * attack.additional_strike_delay), 1),
                attack.additional_hits_on_same_target,
                speed,
                attack.forward_momentum + momentumBonus,
                attack.allow_momentum_airborne,
                attack.movement_speed,
                attack.movement_slipperiness + slipBonus,
                range,
                attack.hitbox,
                attack.animation,
                new AttackContext(spellId, attack.id, curvedRatio)
        );
    }

    /// Rebuilds what `SpellExecution.performSpell` resolved when the cast was released, from the curved
    /// ratio the attack carries. Both are pure functions of static spell data, so the return leg
    /// reconstructs them rather than transporting them.
    private record ResolvedCharge(float outputMultiplier, @Nullable Spell.Modifier modifier) {
        static final ResolvedCharge NONE = new ResolvedCharge(1F, null);
    }
    private static ResolvedCharge resolveCharge(@Nullable RegistryEntry<Spell> spellEntry, float curvedRatio) {
        var charge = SpellParameters.chargeConfigOf(spellEntry);
        if (charge == null) { return ResolvedCharge.NONE; }
        return new ResolvedCharge(
                SpellParameters.chargeOutputMultiplier(spellEntry, curvedRatio),
                SpellModifiers.scaledBy(charge.bonus, curvedRatio));
    }

    @Nullable public static Spell.Delivery.Melee.Attack resolveAttackData(PlayerEntity attacker, World world, @Nullable AttackContext context) {
        if (context == null) {
            return null;
        }
        return resolveAttackData(attacker, world, context.spellId(), context.attackId()).attack;
    }

    public record ResolutionResult(
            RegistryEntry<Spell> spell,
            Spell.Delivery.Melee melee,
            Spell.Delivery.Melee.Attack attack
    ) {}
    @Nullable public static ResolutionResult resolveAttackData(PlayerEntity attacker, World world, Identifier spellId, String attackId) {
        var spellEntry = SpellRegistry.from(world).getEntry(spellId).orElse(null);
        if (spellEntry == null) {
            return null;
        }

        var spell = spellEntry.value();
        if (spell.deliver.type == Spell.Delivery.Type.MELEE && spell.deliver.melee != null) {
            var allAttacks = allAttacksOf(attacker, spell.deliver.melee.attacks, spellEntry);
            for (var attack : allAttacks.attacks()) {
                if (attack.id.equals(attackId)) {
                    return new ResolutionResult(spellEntry, spell.deliver.melee, attack);
                }
            }
        }

        return null;
    }

    public static List<Integer> detectTargets(PlayerEntity player, Attack attack) {
        var hitbox = attack.hitbox();
        var range = attack.range();
        var hitboxSize = new Vec3d(hitbox.width * range, hitbox.height * range, hitbox.length * range);
        var result = TargetFinder.findAttackTargetResult(player, null, hitboxSize, hitbox.arc, range, hitbox.roll);

        return result.entities.stream().map(Entity::getId).toList();
    }

    private static final Supplier<Boolean> REPLAY = Suppliers.memoize(() -> Platform.util().isModLoaded("replaymod"));

    public static void broadcastAttackFx(ServerPlayerEntity player, AttackContext attackContext) {
        var world = player.getWorld();
        var resolved = resolveAttackData(player, world, attackContext.spellId(), attackContext.attackId());
        var attackData = resolved != null ? resolved.attack() : null;
        if (attackData != null) {
            // Saving the attack on server side - mainly for the slipperiness
            var attackSpeedMultiplier = AttributeModifierUtil.multipliersOf(EntityAttributes.GENERIC_ATTACK_SPEED, player);
            var curvedRatio = MathHelper.clamp(attackContext.charge(), 0F, 1F); // Client supplied
            var charge = resolveCharge(resolved.spell(), curvedRatio);
            // The full modifier list (not `List.of()`): the slipperiness stored here drives server
            // side movement, so it has to match the value the client is already sliding with.
            var modifiers = allAttacksOf(player, resolved.melee().attacks, resolved.spell(), charge.modifier()).spellModifiers();
            var attack = convert(player, attackContext.spellId(), attackData, attackSpeedMultiplier, modifiers, curvedRatio);
            ((SpellCaster.Player) player).setMeleeSkillAttack(new ActiveAttack(attack, player.age, player.getMainHandStack().getItem()));
            // Sending fx to clients - animation, sound, particles
            var trackers = Platform.tracking(player);
            float speed = (float) (attackData.attack_speed_multiplier * AttributeModifierUtil.multipliersOf(EntityAttributes.GENERIC_ATTACK_SPEED, player));
            if (REPLAY.get()) {
                AnimationHelper.sendAnimation(player, trackers, SpellCast.Animation.RELEASE, attackData.animation, speed);
            } else {
                AnimationHelper.sendAnimationExcluding(player, trackers, SpellCast.Animation.RELEASE, attackData.animation, speed);
            }
            SoundHelper.playSound(player.getWorld(), player, attackData.swing_sound);
            var swingVisuals = attackData.visuals.resolved(Fx.Context.NONE);
            ParticleHelper.sendBatches(player, swingVisuals.particles, 1, trackers);
            ModelEffectHelper.spawn(player.getWorld(), player.getPos(), player.getYaw(), swingVisuals.models, player);
        }
    }

    /// Melee skills land their damage through vanilla `player.attack(...)`, which reads
    /// `GENERIC_ATTACK_DAMAGE` — an attribute only the main hand contributes to. A spell of the
    /// dual wielding school swings both weapons, so the power difference between the two schools is
    /// expressed here as a damage multiplier over the single handed school.
    ///
    /// Returns the bonus fraction (`0` for every other school), not the multiplier itself, ready to
    /// be handed to an `ADD_MULTIPLIED_TOTAL` modifier.
    private static float dualWieldDamageBonus(PlayerEntity player, @Nullable Spell spell) {
        if (spell == null || spell.school != ExternalSpellSchools.PHYSICAL_MELEE_DUAL) {
            return 0F;
        }
        var query = new SpellSchool.QueryArgs(player);
        var singleHanded = ExternalSpellSchools.PHYSICAL_MELEE.getValue(SpellSchool.Trait.POWER, query);
        if (singleHanded <= 0) {
            return 0F;
        }
        var dualWielded = ExternalSpellSchools.PHYSICAL_MELEE_DUAL.getValue(SpellSchool.Trait.POWER, query);
        return (float) (dualWielded / singleHanded) - 1F;
    }

    private static final Identifier DAMAGE_MODIFIER_ID = Identifier.of(SpellEngineMod.ID, "melee_attack");
    private static final Identifier DUAL_WIELD_MODIFIER_ID = Identifier.of(SpellEngineMod.ID, "melee_attack_dual_wield");
    private static final Identifier CHARGE_MODIFIER_ID = Identifier.of(SpellEngineMod.ID, "melee_attack_charge");
    public static void performAttackAgainstTargets(ServerPlayerEntity player, AttackContext context, int[] targetIds) {
        var world = player.getWorld();
        var focusMode = focusMode();
        var attributeInstance = player.getAttributes().getCustomInstance(EntityAttributes.GENERIC_ATTACK_DAMAGE);
        EntityAttributeModifier appliedDamageModifier = null;
        EntityAttributeModifier appliedDualWieldModifier = null;
        EntityAttributeModifier appliedChargeModifier = null;
        // Arrived from the client, so it is never trusted as-is.
        var curvedRatio = MathHelper.clamp(context.charge(), 0F, 1F);
        try {
            var lastAttackTime = ((LivingEntityAccessor)player).spellEngine_getLastAttackedTicks();
            var targets = new ArrayList<Entity>();
            var resolvedContext = resolveAttackData(player, world, context.spellId, context.attackId);
            var spellEntry = resolvedContext.spell();
            ((SpellCaster.Player)player).setActiveMeleeSkill(spellEntry);
            var attack = resolvedContext.attack();
            Sound impactSound = null;
            int impactSoundLimit = 0;
            var resolvedCharge = resolveCharge(spellEntry, curvedRatio);
            var charge = resolvedCharge.outputMultiplier();
            var modifiers = SpellModifiers.of(player, spellEntry, resolvedCharge.modifier());
            var damageMultiplierBase = 0F;
            for (var modifier : modifiers) {
                damageMultiplierBase += modifier.melee_damage_multiplier;
            }
            // Read before any temporary modifier lands, so it cannot inflate its own ratio. Kept as a
            // separate modifier rather than summed into the one below: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so this way percentage bonuses scale the dual
            // wielded swing instead of the main hand one.
            var dualWieldBonus = dualWieldDamageBonus(player, spellEntry != null ? spellEntry.value() : null);
            if (dualWieldBonus != 0 && attributeInstance != null) {
                appliedDualWieldModifier = new EntityAttributeModifier(DUAL_WIELD_MODIFIER_ID, dualWieldBonus, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedDualWieldModifier);
            }
            // Melee skills land their damage through vanilla `player.attack(...)`, which the
            // `ImpactContext` never reaches, so a partial CHARGE release scales the swing here.
            // Kept separate for the same reason as the dual wield bonus: `ADD_MULTIPLIED_TOTAL`
            // modifiers compose multiplicatively, so the charge scales the whole swing rather
            // than being diluted by the flat bonuses below.
            if (charge != 1F && attributeInstance != null) {
                appliedChargeModifier = new EntityAttributeModifier(CHARGE_MODIFIER_ID, charge - 1F, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                attributeInstance.addTemporaryModifier(appliedChargeModifier);
            }
            if (attack != null && attributeInstance != null) {
                var damageModifierAmount = attack.damage_bonus + damageMultiplierBase;
                if (damageModifierAmount != 0) {
                    appliedDamageModifier = new EntityAttributeModifier(DAMAGE_MODIFIER_ID, damageModifierAmount, EntityAttributeModifier.Operation.ADD_MULTIPLIED_TOTAL);
                    attributeInstance.addTemporaryModifier(appliedDamageModifier);
                }
                impactSound = attack.impact_sound;
                impactSoundLimit = attack.impact_sound_cap > 0 ? attack.impact_sound_cap : 999;
            }
            var attackRange = spellEntry != null ? SpellParameters.getRangeCurved(player, spellEntry, curvedRatio) : (float)player.getEntityInteractionRange();

            for (int targetId : targetIds) {
                var target = world.getEntityById(targetId);
                if (target != null && target.isAttackable()) {
                    if (!EntityRelations.actionAllowed(
                            focusMode, SpellTarget.Intent.HARMFUL,
                            player, target)) {
                        continue;
                    }

                    var distanceGuard = (attackRange + largesSideLength(target.getBoundingBox())) * 1.2F; // Adding some tolerance
                    if (player.squaredDistanceTo(target) > (distanceGuard * distanceGuard) ) {
                        continue;
                    }

                    var timeUntilRegen = target.timeUntilRegen;
                    target.timeUntilRegen = 0;
                    ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(100);
                    player.attack(target);
                    if (impactSound != null && impactSoundLimit > 0) {
                        SoundHelper.playSound(target.getWorld(), target, impactSound);
                        impactSoundLimit -= 1;
                    }
                    targets.add(target);
                    target.timeUntilRegen = timeUntilRegen;
                }
            }

            if (!targets.isEmpty()) {
                var impactContext = new SpellExecution.ImpactContext()
                        .position(player.getPos())
                        .charge(curvedRatio)
                        .chargeModifier(resolvedCharge.modifier());
                SpellImpacts.meleeImpact(player, targets, spellEntry, impactContext);
            }
            ((LivingEntityAccessor)player).spellEngine_setLastAttackedTicks(lastAttackTime);
        } catch (Exception e) {
            System.err.println("Failed to perform melee attack: " + e.getMessage());
        }
        if (appliedDamageModifier != null) {
            attributeInstance.removeModifier(appliedDamageModifier);
        }
        if (appliedDualWieldModifier != null) {
            attributeInstance.removeModifier(appliedDualWieldModifier);
        }
        if (appliedChargeModifier != null) {
            attributeInstance.removeModifier(appliedChargeModifier);
        }
        ((SpellCaster.Player)player).setActiveMeleeSkill(null);
    }

    private static SpellTarget.FocusMode focusMode() {
        return SpellEngineMod.config.melee_skills_area_focus_mode ? SpellTarget.FocusMode.AREA : SpellTarget.FocusMode.DIRECT;
    }

    private static float largesSideLength(Box boundingBox) {
        double x = boundingBox.getLengthX();
        double y = boundingBox.getLengthY();
        double z = boundingBox.getLengthZ();
        return Math.max((float)x, Math.max((float)y, (float)z));
    }
}

package net.spell_engine.internals.delivery.melee;

import net.minecraft.client.MinecraftClient;
import net.minecraft.entity.Entity;
import net.minecraft.entity.mob.HostileEntity;
import net.minecraft.entity.player.PlayerEntity;
import net.minecraft.util.hit.BlockHitResult;
import net.minecraft.util.hit.HitResult;
import net.minecraft.util.math.Box;
import net.minecraft.util.math.MathHelper;
import net.minecraft.util.math.Vec3d;
import net.minecraft.world.RaycastContext;
import net.spell_engine.compat.MeleeCompat;
import net.spell_engine.utils.VectorHelper;
import org.jetbrains.annotations.Nullable;

import java.util.List;
import java.util.stream.Collectors;

public class TargetFinder {
    public static class TargetResult {
        public Entity cursorTarget;
        public List<Entity> entities;
        public OrientedBoundingBox obb;
        public TargetResult(@Nullable Entity cursorTarget, List<Entity> entities, OrientedBoundingBox obb) {
            this.entities = entities;
            this.obb = obb;
        }
    }

    public static TargetResult findAttackTargetResult(PlayerEntity player, @Nullable Entity cursorTarget, Vec3d hitboxSize, double arc, double attackRange, float roll) {
//        long startTime = System.nanoTime();
        Vec3d origin = getInitialTracingPoint(player);
        List<Entity> entities = getInitialTargets(player, cursorTarget, attackRange);

        boolean isSpinAttack = arc > 180;
        Vec3d size = hitboxSize;
        var obb = new OrientedBoundingBox(origin, size, player.getPitch(), player.getYaw(), roll);
        if (!isSpinAttack) {
            obb = obb.offsetAlongAxisZ(size.z / 2F);
        }
        obb.updateVertex();

        var collisionFilter = new CollisionFilter(obb);
        entities = collisionFilter.filter(entities);
        var radialFilter = new RadialFilter(origin, obb.axisZ, attackRange, arc);
        entities = radialFilter.filter(entities);
//        long elapsedTime = System.nanoTime() - startTime;
//        System.out.println("TargetResult findAttackTargetResult (ms): " + ((double)elapsedTime) / 1000000.0);
        return new TargetResult(cursorTarget, entities, obb);
    }

    public static Vec3d getInitialTracingPoint(PlayerEntity player) {
        double shoulderHeight = player.getHeight() * 0.15 * player.getScaleFactor();
        return player.getEyePos().subtract(0, shoulderHeight, 0);
    }

    public static List<Entity> getInitialTargets(PlayerEntity player, Entity cursorTarget, double attackRange) {
        Box box = player.getBoundingBox().expand(attackRange * 2F + 1.0);
        List<Entity> entities = player
                .getWorld()
                .getOtherEntities(player, box, entity ->  !entity.isSpectator() && entity.canHit())
                .stream()
                .filter(entity -> entity != player
                        && entity.isAttackable()
                        && entity != cursorTarget
                        // && TargetHelper.isHitAllowed(false, TargetHelper.getRelation(player, entity)) // isDirect: false due to not being the cursor target
                        && (!entity.equals(player.getVehicle()) || isAttackableMount(entity)))
                .collect(Collectors.toList());
        if (cursorTarget != null && cursorTarget.isAttackable()) {
            entities.add(cursorTarget);
        }
        return entities;
    }

    public static boolean isAttackableMount(Entity entity) {
        return entity instanceof HostileEntity || MeleeCompat.isEntityHostileVehicle.apply(entity);
    }

    public interface Filter {
        List<Entity> filter(List<Entity> entities);
    }

    public static class CollisionFilter implements Filter {
        private OrientedBoundingBox obb;

        public CollisionFilter(OrientedBoundingBox obb) {
            this.obb = obb;
        }

        @Override
        public List<Entity> filter(List<Entity> entities) {
            return entities.stream()
                    .filter(entity -> obb.intersects(entity.getBoundingBox().expand(entity.getTargetingMargin()))
                                || obb.contains(entity.getPos().add(0, entity.getHeight() / 2F, 0))
                    )
                    .collect(Collectors.toList());
        }
    }

    public static class RadialFilter implements Filter {
        final private Vec3d origin;
        final private Vec3d orientation;
        final private double attackRange;
        final private double attackAngle;

        public RadialFilter(Vec3d origin, Vec3d orientation, double attackRange, double attackAngle) {
            this.origin = origin;
            this.orientation = orientation;
            this.attackRange = attackRange;
            this.attackAngle = MathHelper.clamp(attackAngle, 0, 360);
        }

        @Override
        public List<Entity> filter(List<Entity> entities) {
            return entities.stream()
                    .filter(entity -> {
                        var maxAngleDif = (attackAngle / 2.0);
                        Vec3d distanceVector = VectorHelper.distanceVector(origin, entity.getBoundingBox());
                        Vec3d positionVector = entity.getPos().add(0, entity.getHeight() / 2F, 0).subtract(origin);
                        return distanceVector.length() <= attackRange
                                && ((attackAngle == 0)
                                    || (VectorHelper.angleBetween(positionVector, orientation) <= maxAngleDif
                                    || VectorHelper.angleBetween(distanceVector, orientation) <= maxAngleDif))
                                && (rayContainsNoObstacle(origin, origin.add(distanceVector))
                                    || rayContainsNoObstacle(origin, origin.add(positionVector)));
                    })
                    .collect(Collectors.toList());
        }

        private static boolean rayContainsNoObstacle(Vec3d start, Vec3d end) {
            var client = MinecraftClient.getInstance();
            BlockHitResult hit = null;
            if (client.world != null) {
                hit = client.world.raycast(new RaycastContext(start, end, RaycastContext.ShapeType.COLLIDER, RaycastContext.FluidHandling.NONE, client.player));
            }
            if (hit != null) {
                return hit.getType() != HitResult.Type.BLOCK;
            }
            return false;
        }
    }
}

public static void handleAttackFxBroadcast(Packets.AttackFxBroadcast packet, MinecraftServer server, ServerPlayerEntity player) {
    ServerWorld world = Iterables.tryFind(server.getWorlds(), (element) -> element == player.getWorld())
            .orNull();
    if (world == null || world.isClient) {
        return;
    }

    world.getServer().executeSync(() -> {
        Melee.broadcastAttackFx(player, packet.attackContext());
    });
}

public static void createEcho(LivingDamageEvent.Post event) {
    var damageSource = event.getSource();
    if (damageSource.getEntity() instanceof LivingEntity attacker && (damageSource.getDirectEntity() == attacker || damageSource.getDirectEntity() instanceof AbstractArrow) && !(damageSource instanceof SpellDamageSource)) {
        var effect = attacker.getEffect(MobEffectRegistry.ECHOING_STRIKES);
        if (effect == null) {
            return;
        }
        var data = EchoingStrikesData.get(attacker);
        if (!data.hasHitsRemaining()) {
            attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
            return;
        }
        var level = attacker.level();
        var percent = getDamageModifier(effect.getAmplifier(), attacker);
        var target = event.getEntity();
        if (damageSource.isDirect()) {
            createEchoingSword(attacker, level, target, event.getNewDamage() * percent);
        } else {
            createEchoingArrow(attacker, level, target, event.getNewDamage() * percent);
        }

        data.decrementHit();
        if (!data.hasHitsRemaining()) {
            attacker.removeEffect(MobEffectRegistry.ECHOING_STRIKES);
        }
    }
}

    public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
        entity.addEffect(new MobEffectInstance(MobEffectRegistry.ECHOING_STRIKES, 2 * 20 * 60, getAmplifierForLevel(spellLevel, entity), false, false, true));
        EchoingStrikesData.get(entity).setHitCount(getHitCount(spellLevel, entity));

        Vec3 vec3 = entity.position().add(0, 0.5, 0);
//        MagicManager.spawnParticles(level, new BlastwaveParticleOptions(1f, .333f, 1f, 2.5f), vec3.x, vec3.y, vec3.z, 1, 0, 0, 0, 0, false);
        MagicManager.spawnParticles(level, new ShockwaveParticleOptions(new Vector3f(1f, .333f, 1f), 10 * -1.5f * .05f, true), vec3.x, vec3.y, vec3.z, 1, 0, 0, 0, 0, true);
        MagicManager.spawnParticles(level, new ShockwaveParticleOptions(new Vector3f(1f, .333f, 1f), 20 * -1.5f * .05f, true), vec3.x, vec3.y, vec3.z, 1, 0, 0, 0, 0, true);
        MagicManager.spawnParticles(level, new ShockwaveParticleOptions(new Vector3f(1f, .333f, 1f), 30 * -1.5f * .05f, true), vec3.x, vec3.y, vec3.z, 1, 0, 0, 0, 0, true);
        super.onCast(level, spellLevel, entity, castSource, playerMagicData);
    }

public void onEffectStarted(LivingEntity pLivingEntity, int pAmplifier) {
    super.onEffectStarted(pLivingEntity, pAmplifier);
    // default count
    EchoingStrikesData.get(pLivingEntity).setHitCount(1);
}

public void onEffectRemoved(LivingEntity pLivingEntity, int pAmplifier) {
    EchoingStrikesData.remove(pLivingEntity);
}

private static void createEchoingSword(LivingEntity attacker, Level level, LivingEntity target, float damage) {
    EchoingSword echo = new EchoingSword(EntityRegistry.ECHOING_SWORD.get(), level);
    // todo: real spawn logic
    echo.moveTo(target.getBoundingBox().getCenter().add(new Vec3(2.5, 0, 0).yRot(level.getRandom().nextFloat() * Mth.TWO_PI)).add(Utils.getRandomVec3(1.75)));
    echo.setHomingTarget(target);
    echo.moveAndRotateTowards(target.getBoundingBox().getCenter());
    echo.setExplosionRadius(EchoingStrikesSpell.radius);
    echo.setDamage(damage);
    echo.setOwner(attacker);
    attacker.level.addFreshEntity(echo);
}

private static void createEchoingArrow(LivingEntity attacker, Level level, LivingEntity target, float damage) {
    EchoingArrowProjectile arrow = new EchoingArrowProjectile(EntityRegistry.ECHOING_ARROW.get(), level);
    Vec3 targetPos = target.getBoundingBox().getCenter();
    Vec3 arrowPos = attacker.position().lerp(targetPos, 0.35);
    Vec3 right = targetPos.subtract(arrowPos).normalize().cross(new Vec3(0, 1, 0));
    Vec3 spawnPos = arrowPos
            .add(right.scale((1 + level.getRandom().nextFloat() * 4) * (level.getRandom().nextBoolean() ? 1 : -1)))
            .add(0, (level.getRandom().nextFloat() - 0.25) * 6, 0);
    arrow.moveTo(spawnPos);
    arrow.setHomingTarget(target);
    arrow.setDamage(damage);
    arrow.setOwner(attacker);
    attacker.level.addFreshEntity(arrow);
}

public static float getDamageModifier(int effectAmplifier, @Nullable LivingEntity caster) {
    var power = caster == null ? 1 : SpellRegistry.ECHOING_STRIKES_SPELL.get().getEntityPowerMultiplier(caster);
    return (effectAmplifier + 1) * power * PERCENT_PER_AMPLIFIER;
}

package io.redspace.ironsspellbooks.effect;

import io.redspace.ironsspellbooks.registries.DataAttachmentRegistry;
import net.minecraft.world.entity.LivingEntity;
import net.neoforged.neoforge.attachment.IAttachmentHolder;

public class EchoingStrikesData {
    private int hitCount;
    public int vfxTimestamp;

    public EchoingStrikesData(int hitsRemaining) {
        this.hitCount = hitsRemaining;
    }

    public EchoingStrikesData(IAttachmentHolder holder) {

    }

    public int getHitCount() {
        return hitCount;
    }

    public void setHitCount(int hitCount) {
        this.hitCount = hitCount;
    }

    public boolean hasHitsRemaining() {
        return hitCount > 0;
    }

    public void decrementHit() {
        if (hitCount > 0) {
            hitCount--;
        }
    }

    public void clear() {
        hitCount = 0;
    }

    public static EchoingStrikesData get(LivingEntity entity) {
        return entity.getData(DataAttachmentRegistry.ECHOING_STRIKES_DATA);
    }

    public static void remove(LivingEntity livingEntity) {
        livingEntity.removeData(DataAttachmentRegistry.ECHOING_STRIKES_DATA);
    }

    public static boolean has(LivingEntity livingEntity) {
        return livingEntity.hasData(DataAttachmentRegistry.ECHOING_STRIKES_DATA);
    }
}

public void tick() {
    this.baseTick();
    var target = getHomingTarget();
    if (lastHomingPos == Vec3.ZERO && target == null) {
        die();
        return;
    } else if (target != null) {
        lastHomingPos = target.getBoundingBox().getCenter();
    }
    this.setOldPosAndRot();
    if (tickCount == 1) {
        playAnimation("summoned_sword_basic_downswing");
    }
    moveAndRotateTowards(lastHomingPos);
    if (tickCount == ANIM_HIT_TIMESTAMP) {
        performHit();
    }
    if (tickCount >= ANIM_LENGTH) {
        die();
    }
}

private static void createEchoingSword(LivingEntity attacker, Level level, LivingEntity target, float damage) {
    EchoingSword echo = new EchoingSword(EntityRegistry.ECHOING_SWORD.get(), level);
    // todo: real spawn logic
    echo.moveTo(target.getBoundingBox().getCenter().add(new Vec3(2.5, 0, 0).yRot(level.getRandom().nextFloat() * Mth.TWO_PI)).add(Utils.getRandomVec3(1.75)));
    echo.setHomingTarget(target);
    echo.moveAndRotateTowards(target.getBoundingBox().getCenter());
    echo.setExplosionRadius(EchoingStrikesSpell.radius);
    echo.setDamage(damage);
    echo.setOwner(attacker);
    attacker.level.addFreshEntity(echo);
}

public void moveAndRotateTowards(Vec3 target) {
    Vec3 vec3 = target.subtract(this.position()).normalize();
    Vec3 wantedPos = target.subtract(vec3.scale(range * .6f));
    Vec3 wantedMotion = wantedPos.subtract(this.position()).scale(0.1f);
    this.setDeltaMovement(getDeltaMovement().lerp(wantedMotion, 0.05f));
    this.move(MoverType.SELF, getDeltaMovement());
    this.rotateWithMotion();
}

private void performHit() {
    this.playSound(SoundRegistry.ECHOING_STRIKE.get(), 1.5f, Utils.random.nextIntBetweenInclusive(8, 12) * .1f);
    if (level.isClientSide) {
        return;
    }
    Vec3 vec3 = lastHomingPos.subtract(this.position()).normalize();
    float range = 2f;
    Vec3 center = this.position().add(vec3.scale(range));
    AABB collider = AABB.ofSize(center, explosionRadius * 2, explosionRadius * 2, explosionRadius * 2).inflate(1);
    MagicManager.spawnParticles(level, ParticleHelper.UNSTABLE_ENDER, center.x, center.y, center.z, 25, 0, 0, 0, .18, false);
    MagicManager.spawnParticles(level, new BlastwaveParticleOptions(SpellRegistry.ECHOING_STRIKES_SPELL.get().getSchoolType().getTargetingColor(), explosionRadius * .9f), center.x, center.y, center.z, 1, 0, 0, 0, 0, true);
    var explosionRadiusSqr = explosionRadius * explosionRadius;
    var entities = level.getEntities(this, collider);
    for (Entity entity : entities) {
        double distanceSqr = entity.distanceToSqr(center);
        if (distanceSqr < explosionRadiusSqr && canHitEntity(entity) && Utils.hasLineOfSight(level, this.position(), entity.getBoundingBox().getCenter(), true)) {
            double p = Mth.clamp((1 - distanceSqr / explosionRadiusSqr) + .4f, 0, 1);
            float damage = (float) (this.damage * p);
            entity.invulnerableTime = 0;
            DamageSources.applyDamage(entity, damage, SpellRegistry.ECHOING_STRIKES_SPELL.get().getDamageSource(this, getOwner()));
        }
    }
}

private void die() {
    if (!level.isClientSide) {
        MagicManager.spawnParticles(level, ParticleHelper.ENDER_SPARKS, getX(), getY(), getZ(), 25, .1, .1, .1, 0.25, false);
    }
    this.discard();
}

public boolean shouldBeSaved() {
    return false;
}

public Entity getHomingTarget() {
    if (this.cachedHomingTarget != null && !this.cachedHomingTarget.isRemoved()) {
        return this.cachedHomingTarget;
    } else if (this.homingTargetUUID != null && this.level instanceof ServerLevel) {
        this.cachedHomingTarget = ((ServerLevel) this.level).getEntity(this.homingTargetUUID);
        return this.cachedHomingTarget;
    } else {
        return null;
    }
}

public void setHomingTarget(LivingEntity entity) {
    this.homingTargetUUID = entity.getUUID();
    this.cachedHomingTarget = entity;
    setCursorHoming(false);
}

protected boolean canHitEntity(@NotNull Entity pTarget) {
    var owner = getOwner();
    return super.canHitEntity(pTarget) && pTarget != owner && (owner == null || !(owner.isAlliedTo(pTarget) || pTarget.isAlliedTo(owner)));
}

public void writeSpawnData(RegistryFriendlyByteBuf buffer) {
    var owner = getOwner();
    buffer.writeInt(owner == null ? 0 : owner.getId());
    var homingTarget = getHomingTarget();
    buffer.writeInt(homingTarget == null ? 0 : homingTarget.getId());
}

public void readSpawnData(RegistryFriendlyByteBuf additionalData) {
    Entity owner = this.level.getEntity(additionalData.readInt());
    if (owner != null) {
        this.setOwner(owner);
    }
    Entity homingTarget = this.level.getEntity(additionalData.readInt());
    if (homingTarget != null) {
        this.cachedHomingTarget = homingTarget;
        this.homingTargetUUID = homingTarget.getUUID();
    }
}

public static void handle(PacketAddFadingLight packet, Minecraft minecraft, Player player) {
    if (LightManager.shouldUpdateDynamicLight() || LightManager.dynamicLightsContext != null) {
        var event = new FadeLightTimedEvent(minecraft.level, new Vec3(packet.x, packet.y, packet.z), Config.TOUCH_LIGHT_DURATION.get(), Config.TOUCH_LIGHT_LUMINANCE.get());
        EventQueue.getClientQueue().addEvent(event);

        if (LightManager.dynamicLightsContext != null) {
            LightManager.dynamicLightsContext.dynamicLightBehaviorManager().add(event);
        }
    }
}

public CastResolveType onCastOnEntity(ItemStack stack, LivingEntity caster, Entity target, InteractionHand hand, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    resolver.onResolveEffect(caster.getCommandSenderWorld(), new EntityHitResult(target));
    ParticleEmitter particleEmitter = resolveEmitter(spellContext, target.position);
    particleEmitter.tick(caster.level);
    playResolveSound(spellContext, caster.level(), target.position());
    addFadingLight(caster.level(), target.blockPosition().getX() + 0.5, target.blockPosition().getY() + 0.5, target.blockPosition().getZ() + 0.5);
    return spellContext.getCaster().getCasterType() != SpellContext.CasterType.RUNE ? CastResolveType.SUCCESS : CastResolveType.SUCCESS_NO_EXPEND;
}

public void addFadingLight(Level level, double x, double y, double z) {
    Networking.sendToNearbyClient(level, BlockPos.containing(x, y, z), new PacketAddFadingLight(x, y, z));
}

